def poblar_catalogo_tipos(apps, schema_editor):
    TipoNotificacion = apps.get_model('notificaciones', 'TipoNotificacion')
    Notificacion = apps.get_model('notificaciones', 'Notificacion')
    db_alias = schema_editor.connection.alias
    nombres = {
        'comunicacion': 'Comunicación',
        'evaluacion': 'Evaluación',
    }
    codigos = set(
        Notificacion.objects.using(db_alias)
        .values_list('tipo', flat=True)
        .distinct()
    )
    codigos.update(nombres)
    tipos = {}
    for codigo in codigos:
        tipos[codigo] = TipoNotificacion.objects.using(db_alias).create(
            codigo=codigo,
            nombre=nombres.get(codigo, codigo.replace('_', ' ').capitalize()),
        )

    lote = []
    for notificacion in (
        Notificacion.objects.using(db_alias)
        .only('id', 'tipo')
        .iterator(chunk_size=1000)
    ):
        notificacion.tipo_catalogo_id = tipos[notificacion.tipo].pk
        lote.append(notificacion)
        if len(lote) == 1000:
            Notificacion.objects.using(db_alias).bulk_update(
                lote,
                ['tipo_catalogo'],
                batch_size=1000,
            )
            lote.clear()
    if lote:
        Notificacion.objects.using(db_alias).bulk_update(
            lote,
            ['tipo_catalogo'],
            batch_size=1000,
        )


